#!/usr/bin/env python3
# cartao.py (ficheiro unico): faz os indices do navegador (_NAV/*.IDX) no cartao todo.
# Nao mexe em nomes nem na ordem dos ficheiros e nao adivinha maquinas: a maquina ([48K], [128K]...)
# so' aparece no navegador se ja' estiver no nome do ficheiro. Entra tudo, menos BIN, SYS, TMP e System Volume Information (na raiz)
# e o _NAV; as pastas primeiro (com [up] fora da raiz), depois os ficheiros, por ordem.
#
#   python cartao.py E:\            so' mostra o que faria
#   python cartao.py E:\ --fazer    faz
#
# Barra de baixo do navegador hi-res:  --pasta DEMOS GAMES PT3  (ou MUSICA/PT3=PT3)
#   ou no config.ini ao lado deste (seccao [pastas])
# Nomes para o navegador normal de 32 colunas (sem hi-res):  --normal
import os, sys, argparse

AQUI = os.path.dirname(os.path.abspath(__file__))

FONTES = {
    'maquina': "# So' a etiqueta da maquina no nome ([48K], [128K], (128K), [TC2068]...), para o gera_nav.py.\nimport re\n\nETIQ = re.compile(r'[\\[(](16K|48K(-AY)?[?~]?|128K[?~]?|\\+2A?|\\+3|Pentagon|Scorpion|TC2048|TC2068|TS2068|SamRam|Didaktik)[\\])]', re.I)\n\n",
    'gera_nav': '#!/usr/bin/env python3\n# Cria os indices do navegador (_NAV/*.IDX) em cada pasta do cartao SD.\n# Junta, para cada ficheiro: nome grande, nome 8.3 (o que os plugins precisam) e maquina.\n#\n#   python3 gera_nav.py /run/media/$USER/SD/GAMES [/run/media/$USER/SD/DEMOS ...]\n#   Windows:  py gera_nav.py E:\\    (E: = letra do cartao)\n#   --pasta DEMOS GAMES MUSICA/PT3=PT3   pastas da barra de baixo do navegador hi-res\n#              (nome ou caminho dentro do cartao; "=NOME" e\' o que aparece: [PT3])\n#   --largura 17   nomes para o navegador normal (32 colunas); por defeito 46 (hi-res)\n#\n# Tem de ser o cartao montado (FAT/vfat): o nome 8.3 vem do proprio Linux\n# (ioctl VFAT_IOCTL_READDIR_BOTH), que da\' o nome curto tal como esta\' gravado.\n# Corre tambem nas subpastas. Sem --fazer so\' mostra o que faria.\n#\n# Formato (tudo little-endian):\n#   _NAV/NAV.IDX   "NAV1", u16 total de entradas, u16 reservado,\n#                  29 x u16: quantos ha\' em DIR, 0-9, A..Z, outros\n#                  6 x 29 x u16: o mesmo, so\' para cada maquina (0..5, como no byte 0 abaixo)\n#   _NAV/DIR.IDX, 0.IDX, A.IDX ... Z.IDX, _.IDX   registos de 64 bytes, ordenados:\n#     0      maquina: 0 desconhecida, 1 48K, 2 48K+AY, 3 128K, 4 Timex, 5 outra\n#            (+3, Pentagon...); bit 7 = palpite\n#     1      0 ficheiro, 1 pasta\n#     2-3    reservado\n#     4-16   nome 8.3, terminado em 0 (ex. "GHOSTS~1.TAP")\n#     17-63  nome grande sem a etiqueta da maquina, ASCII, terminado em 0 (46 letras no maximo)\nimport os, sys, re, struct, ctypes, argparse, unicodedata\nif os.name != \'nt\':\n    import fcntl\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport maquina as mq\n\n# struct __fat_dirent { long d_ino; __kernel_off_t d_off; unsigned short d_reclen; char d_name[256]; }\nclass FatDirent(ctypes.Structure):\n    _fields_ = [(\'d_ino\', ctypes.c_long), (\'d_off\', ctypes.c_long),\n                (\'d_reclen\', ctypes.c_ushort), (\'d_name\', ctypes.c_char * 256)]\nPar = FatDirent * 2\ndef _IOR(t, n, size): return (2 << 30) | (size << 16) | (ord(t) << 8) | n\nVFAT_IOCTL_READDIR_BOTH = _IOR(\'r\', 1, ctypes.sizeof(Par))\n\ndef ler_pasta_linux(caminho):\n    """[(nome grande, nome 8.3, e\' pasta)] pela ordem do disco"""\n    pastas = {e.name for e in os.scandir(caminho) if e.is_dir()}   # um so\' scandir (sem um stat por entrada)\n    fd = os.open(caminho, os.O_RDONLY | os.O_DIRECTORY)\n    out = []\n    try:\n        while True:\n            d = Par()\n            r = fcntl.ioctl(fd, VFAT_IOCTL_READDIR_BOTH, d)\n            if r <= 0 or d[0].d_reclen == 0: break\n            curto = d[0].d_name[:d[0].d_reclen].decode(\'latin-1\')\n            grande = d[1].d_name[:d[1].d_reclen].decode(\'utf-8\', \'replace\') if d[1].d_reclen else curto\n            if curto in (\'.\', \'..\'): continue\n            out.append((grande, curto.upper(), grande in pastas))\n    finally:\n        os.close(fd)\n    return out\n\n# Windows: o nome 8.3 vem de GetShortPathNameW (no FAT32 o Windows grava sempre o nome curto)\ndef ler_pasta_windows(caminho):\n    from ctypes import wintypes\n    f = ctypes.windll.kernel32.GetShortPathNameW\n    f.argtypes = [wintypes.LPCWSTR, wintypes.LPWSTR, wintypes.DWORD]\n    f.restype = wintypes.DWORD\n    out = []\n    for grande in os.listdir(caminho):\n        cheio = os.path.join(caminho, grande)\n        buf = ctypes.create_unicode_buffer(1024)\n        n = f(cheio, buf, 1024)\n        curto = os.path.basename(buf.value) if n else grande\n        out.append((grande, curto.upper(), os.path.isdir(cheio)))\n    return out\n\ndef ler_pasta(caminho):\n    return ler_pasta_windows(caminho) if os.name == \'nt\' else ler_pasta_linux(caminho)\n\nGRUPOS = [\'DIR\', \'0\'] + [chr(c) for c in range(65, 91)] + [\'_\']\n\ndef chave(nome):\n    n = re.sub(r\'^(the|a|an)[ _-]+\', \'\', nome.lower())\n    return re.sub(r\'[^a-z0-9]\', \'\', n) or \'_\'\n\ndef grupo(nome, pasta):\n    # pastas de arrumacao (A..Z, 0-9, #, as de 2 letras, FAVORITOS/GAMES/...) ficam em DIR;\n    # as outras (titulos, colecoes) entram na letra delas, no meio dos ficheiros\n    if pasta: return 0                               # as pastas todas juntas, no inicio, por ordem\n    c = chave(nome)[0]\n    if c.isdigit(): return 1\n    if \'a\' <= c <= \'z\': return 2 + ord(c) - 97\n    return 28\n\nCOD = {\'48K\': 1, \'16K\': 1, \'48K-AY\': 2, \'128K\': 3, \'+2\': 3, \'TC2048\': 4, \'TC2068\': 4, \'TS2068\': 4}\ndef codigo(m):\n    if not m: return 0\n    palp = m.endswith((\'?\', \'~\')); m = m.rstrip(\'?~\')\n    return COD.get(m.upper(), 5) | (0x80 if palp else 0)\n\ndef ascii_spectrum(s):\n    s = unicodedata.normalize(\'NFKD\', s).encode(\'ascii\', \'ignore\').decode()\n    return \'\'.join(c if 32 <= ord(c) < 127 else \'?\' for c in s)\n\nLARG_NOME = 46      # letras do nome na lista: 46 no hi-res (64 colunas), 17 no normal (32)\ndef registo(grande, curto, pasta, cod):\n    vis = mq.ETIQ.sub(\'\', os.path.splitext(grande)[0] if not pasta else grande)\n    vis = re.sub(r\'\\s+\', \' \', vis).strip()\n    ext = \'\' if pasta else os.path.splitext(grande)[1].lower()\n    vis = ascii_spectrum(vis)\n    ext = ascii_spectrum(ext)\n    # comprido demais: primeiro tira os (ano)(editora)... do fim, menos lados/partes\n    while len(vis) + len(ext) > LARG_NOME:\n        m = re.search(r\'\\s*[\\(\\[]([^\\(\\)\\[\\]]*)[\\)\\]]\\s*$\', vis)\n        if not m or re.search(r\'(?i)\\b(side|lado|part|parte|disk|disco|tape|cassete|cassette|block|bloco)\\b\', m.group(1)): break\n        vis = vis[:m.start()].rstrip()\n    if len(vis) + len(ext) > LARG_NOME and len(ext) < LARG_NOME - 4:\n        # o navegador so\' mostra LARG_NOME letras: corta o nome e deixa a extensao a\' vista\n        # e o fim do nome tambem (lados e partes: "Head ov~Part 1.tap" / "Head ov~Part 2.tap")\n        livre = LARG_NOME - len(ext) - 1\n        ini = (livre + 1) // 2\n        vis = vis[:ini].rstrip() + \'~\' + vis[len(vis) - (livre - ini):].lstrip()\n    vis = (vis + ext)[:46]\n    r = bytearray(64)\n    r[0] = cod; r[1] = 1 if pasta else 0\n    c = curto.encode(\'ascii\', \'replace\')[:12]      # 8.3 tem no maximo 12 letras\n    v = vis.encode()[:46]\n    r[4:4 + len(c)] = c                             # o mesmo tamanho dos dois lados: o registo fica com 64\n    r[17:17 + len(v)] = v\n    assert len(r) == 64\n    return bytes(r)\n\nMUSICA = {\'.pt3\', \'.pt2\', \'.pt1\', \'.stc\', \'.sqt\', \'.stp\', \'.psc\', \'.ftc\', \'.fxm\', \'.ay\', \'.mym\'}\nPRIMEIRO = [\'FAVORITOS\', \'GAMES\', \'APPS\', \'DEMOS\']\n\n# pastas de sistema: nao se indexam nem aparecem no navegador\nSISTEMA = {\'BIN\', \'SYS\', \'TMP\', \'SYSTEM VOLUME INFORMATION\'}   # so\' estas (na raiz) e o _NAV ficam escondidas\ndef de_sistema(nome, topo=True):                    # BIN, SYS... so\' contam na raiz (GAMES\\S\\BIN e\' um formato)\n    return nome.upper() == \'_NAV\' or (topo and nome.upper() in SISTEMA)\n\n# So\' entram no indice os ficheiros que o navegador consegue correr: os que tem plugin em\n# /BIN/BPLUGINS do cartao. Sem essa pasta, a lista dos plugins do Bob Fossil que funcionam\n# num Spectrum/Timex com DivMMC (sem os so\' de ZX-UNO: PZX, WAV, RAD). TZX nao tem plugin.\nPLUGINS_BOB = {\'TAP\', \'Z80\', \'SNA\', \'TRD\', \'SCL\', \'BAS\', \'ROM\', \'POK\',\n               \'PT1\', \'PT2\', \'PT3\', \'SQT\', \'STC\', \'STP\', \'FXM\', \'FTC\', \'PSC\', \'MYM\', \'AY\', \'MID\',\n               \'SCR\', \'LCE\', \'IMG\', \'MG1\', \'MG2\', \'MG4\', \'ART\', \'IPH\', \'HAM\', \'ULA\', \'TXT\'}\nCORRE = None                                         # None = todos (--todos)\n\ndef plugins_do_cartao(p):\n    d = os.path.abspath(p)\n    while True:                                      # sobe ate\' encontrar BIN/BPLUGINS\n        for b in (\'BIN\', \'bin\'):\n            pl = os.path.join(d, b, \'BPLUGINS\')\n            if not os.path.isdir(pl): pl = os.path.join(d, b, \'bplugins\')\n            if os.path.isdir(pl):\n                return {f.upper() for f in os.listdir(pl)\n                        if os.path.isfile(os.path.join(pl, f)) and \'.\' not in f}, pl\n        cima = os.path.dirname(d)\n        if cima == d: return None, None\n        d = cima\n\n# A maquina escolhida no navegador e\' tambem a lista que se ve (byte 0 do registo:\n# 0 ?, 1 48K, 2 48K+AY, 3 128K, 4 Timex, 5 outra):\n#   1 Timex 48  : Timex, 48K, 48K+AY e desconhecidos\n#   2 ZX 48K    : 48K, 48K+AY e desconhecidos\n#   3 ZX 128K   : 128K e outras\n#   4 Timex 128 : 128K e Timex\n#   5 TC2068    : Timex (o NAV nao corre no TC2068: sem NMI)\nVISTAS = {1: (0, 1, 2, 4), 2: (0, 1, 2), 3: (3, 5), 4: (3, 4), 5: (4,)}\ndef na_vista(b0, v):\n    if v == 0: return True\n    return (b0 & 0x7f) in VISTAS.get(v, ())\n\ndef corre(nome, ehpasta):\n    if ehpasta or CORRE is None: return True\n    return os.path.splitext(nome)[1][1:].upper() in CORRE\n\ndef processa(pasta, fazer, topo=True):\n    lidas = [e for e in ler_pasta(pasta) if not de_sistema(e[0], topo) and e[1] != \'_NAV\']\n    entradas = [e for e in lidas if corre(e[0], e[2])]\n    fora = len(lidas) - len(entradas)\n    grupos = [[] for _ in GRUPOS]\n    for grande, curto, ehpasta in entradas:\n        m = None\n        if not ehpasta:\n            t = mq.ETIQ.search(grande)\n            m = t.group(1) if t else None\n            if not m and os.path.splitext(grande)[1].lower() in MUSICA:\n                m = \'48K-AY\'                         # musica do chip AY: etiqueta AY no navegador\n            # (a maquina so\' vem da etiqueta que ja\' estiver no nome: nao se adivinha pelo conteudo)\n        k = chave(grande)\n        grupos[grupo(grande, ehpasta)].append((k, registo(grande, curto, ehpasta, codigo(m))))\n    if not topo:                                     # [up]: a pasta de cima, sempre a primeira da lista\n        grupos[0].append((\'\\x00\\x00\', registo(\'[up]\', \'..\', True, 0)))\n    if os.path.dirname(os.path.normpath(pasta)) != os.path.normpath(RAIZ):   # [raiz]: a raiz do cartao, a partir do 2.o nivel\n        if not topo: grupos[0].append((\'\\x00\\x01\', registo(\'[raiz]\', \'/\', True, 0)))\n    n_ent = sum(len(g) for g in grupos)\n    nav = b\'NAV1\' + struct.pack(\'<HH\', n_ent, 0) + b\'\'.join(struct.pack(\'<H\', len(g)) for g in grupos)\n    # contagens por vista (a maquina escolhida no navegador): 6 tabelas de 29 x u16,\n    # 0 = todos, 1..4 = VISTAS, 5 = nao usada\n    for v in range(6):\n        nav += b\'\'.join(struct.pack(\'<H\', sum(1 for _, r in g if na_vista(r[0], v))) for g in grupos)\n    print(\'%s: %d entradas%s  \' % (pasta, n_ent, \' (%d sem plugin, fora)\' % fora if fora else \'\') +\n          \' \'.join(\'%s:%d\' % (GRUPOS[i], len(g)) for i, g in enumerate(grupos) if g))\n    if not fazer: return\n    d = os.path.join(pasta, \'_NAV\')\n    os.makedirs(d, exist_ok=True)\n    novos = {\'NAV.IDX\': nav}\n    for i, g in enumerate(grupos):\n        if g:\n            g.sort(key=lambda x: x[0])\n            novos[GRUPOS[i] + \'.IDX\'] = b\'\'.join(r for _, r in g)\n    # so\' se escreve o que mudou (no cartao cada escrita e\' lenta); os .IDX que ja\' nao servem\n    # (grupos vazios, os X1..X5.IDX de versoes antigas) apagam-se\n    for f in os.listdir(d):\n        if f.upper().endswith(\'.IDX\') and f.upper() not in novos and f.upper() != \'PASTAS.IDX\':\n            os.remove(os.path.join(d, f))\n    for nome, dados in novos.items():\n        f = os.path.join(d, nome)\n        try:\n            if os.path.getsize(f) == len(dados) and open(f, \'rb\').read() == dados: continue\n        except OSError: pass\n        with open(f, \'wb\') as h: h.write(dados)\n\n# /_NAV/PASTAS.IDX na raiz do cartao: ate\' 8 registos de 64 bytes:\n#   0-7  nome (ate\' 6 letras, o que aparece na barra: [DEMOS])\n#   8-63 caminho 8.3 a partir da raiz ("/MUSICA/PT3"), terminado em 0\ndef caminho_curto(raiz, rel):\n    partes = [p for p in re.split(r\'[\\\\/]\', rel) if p]\n    cur, curto = raiz, \'\'\n    for p in partes:\n        ach = [e for e in ler_pasta(cur) if e[2] and e[0].lower() == p.lower()]\n        if not ach: return None\n        cur = os.path.join(cur, ach[0][0]); curto += \'/\' + ach[0][1]\n    return curto\n\ndef procura_pasta(raiz, nome):\n    if \'/\' in nome or \'\\\\\' in nome:\n        return nome if os.path.isdir(os.path.join(raiz, nome)) else None\n    achadas = []\n    for d, subs, _ in os.walk(raiz):\n        subs[:] = sorted(x for x in subs if not de_sistema(x, os.path.normpath(d) == os.path.normpath(raiz)))\n        for x in subs:\n            if x.lower() == nome.lower():\n                achadas.append(os.path.relpath(os.path.join(d, x), raiz))\n    achadas.sort(key=lambda r: (r.count(os.sep), r.lower()))      # a menos funda\n    return achadas[0] if achadas else None\n\ndef escreve_pastas(raiz, pedidas, fazer):\n    regs = []\n    for p in pedidas:\n        nome, _, rot = p.partition(\'=\')\n        rel = procura_pasta(raiz, nome)\n        if not rel: print(\'pasta %s: nao encontrei no cartao\' % nome); continue\n        curto = caminho_curto(raiz, rel)\n        rot = ascii_spectrum(rot or os.path.basename(rel)).upper()[:6]\n        if not curto or len(curto) > 55: print(\'pasta %s: caminho 8.3 comprido demais\' % nome); continue\n        print(\'pasta [%s] = %s (%s)\' % (rot, rel, curto))\n        r = bytearray(64); r[0:len(rot)] = rot.encode(); r[8:8 + len(curto)] = curto.encode(\'ascii\', \'replace\')\n        regs.append(bytes(r))\n    if len(regs) > 8: print(\'so\\\' cabem 8 pastas na barra: fico com as 8 primeiras\'); regs = regs[:8]\n    if not fazer: return\n    d = os.path.join(raiz, \'_NAV\'); os.makedirs(d, exist_ok=True)\n    f = os.path.join(d, \'PASTAS.IDX\')\n    if regs: open(f, \'wb\').write(b\'\'.join(regs))\n    elif os.path.exists(f): os.remove(f)\n\ndef main():\n    try: sys.stdout.reconfigure(errors=\'replace\')   # consola do Windows\n    except Exception: pass\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\'pastas\', nargs=\'+\')\n    ap.add_argument(\'--fazer\', action=\'store_true\')\n    ap.add_argument(\'--todos\', action=\'store_true\', help=\'indexa tambem os ficheiros sem plugin\')\n    ap.add_argument(\'--pasta\', nargs=\'+\', action=\'extend\', default=[], help=\'pastas da barra de baixo (NOME ou CAMINHO[=ROTULO])\')\n    ap.add_argument(\'--largura\', type=int, default=46, help=\'letras do nome (46 hi-res, 17 normal)\')\n    ap.add_argument(\'--so\', nargs=\'*\', default=None, help=\'so\\\' estas pastas (dentro da 1.a), e a raiz sem subpastas\')\n    a = ap.parse_args()\n    global CORRE, LARG_NOME, RAIZ\n    RAIZ = a.pastas[0]\n    LARG_NOME = max(8, min(46, a.largura))\n    if not a.todos:\n        CORRE, onde = plugins_do_cartao(a.pastas[0])\n        if CORRE: print(\'plugins em %s: %s\' % (onde, \' \'.join(sorted(CORRE))))\n        else:\n            CORRE = PLUGINS_BOB\n            print(\'sem /BIN/BPLUGINS: uso a lista do Bob Fossil: \' + \' \'.join(sorted(CORRE)))\n    if a.so is not None:\n        # so\' as pastas pedidas; a raiz do cartao tambem (sem descer), para a lista de cima\n        r = a.pastas[0]\n        processa(r, a.fazer, True)\n        for nome in a.so:\n            p = os.path.join(r, nome)\n            if not os.path.isdir(p): print(\'pasta %s: nao existe\' % nome); continue\n            for raiz, subs, _ in os.walk(p):\n                subs[:] = [s for s in subs if not de_sistema(s, False)]\n                processa(raiz, a.fazer, False)\n    else:\n      for p in a.pastas:\n        for raiz, subs, _ in os.walk(p):\n            topo = os.path.normpath(raiz) == os.path.normpath(p)\n            subs[:] = [s for s in subs if not de_sistema(s, topo)]\n            processa(raiz, a.fazer, topo)\n    if a.pasta: escreve_pastas(a.pastas[0], a.pasta, a.fazer)\n    if not a.fazer: print(\'(nada foi escrito; repete com --fazer)\')\n\nif __name__ == \'__main__\':\n    main()\n',
}


import types
def corre(script, *args):
    nome = script[:-3]
    print('\n>>', script, ' '.join(args), flush=True)
    if 'maquina' not in sys.modules:             # o gera_nav.py faz "import maquina"
        mod = types.ModuleType('maquina'); mod.__file__ = 'maquina.py'
        exec(compile(FONTES['maquina'], 'maquina.py', 'exec'), mod.__dict__); sys.modules['maquina'] = mod
    velho = sys.argv
    sys.argv = [script] + list(args)
    try:
        g = {'__name__': '__main__', '__file__': os.path.join(AQUI, script)}
        exec(compile(FONTES[nome], script, 'exec'), g)
    except SystemExit as e:
        if e.code not in (None, 0): sys.exit('%s parou: %s' % (script, e.code))
    finally:
        sys.argv = velho

# config.ini ao lado do cartao.py (opcional; o que vem na linha de comando ganha):
#   [pastas]            barra de baixo do navegador, por esta ordem (ate' 8)
#   DEMOS               nome da pasta (procura no cartao a menos funda com esse nome)
#   PT3 = MUSICA/PT3    rotulo (ate' 6 letras) = caminho dentro do cartao
#   [opcoes]
#   normal = no         yes = nomes de 17 letras (navegador de 32 colunas)
import configparser
CFG = configparser.ConfigParser(allow_no_value=True, delimiters=('=',), comment_prefixes=('#', ';'))
CFG.optionxform = str
def le_config():
    f = os.path.join(AQUI, 'config.ini')
    if os.path.isfile(f):
        CFG.read(f, encoding='utf-8')
        print('config: %s' % f)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('cartao')
    ap.add_argument('--fazer', action='store_true')
    ap.add_argument('--pasta', nargs='+', action='extend', default=[], help='pastas da barra de baixo do navegador')
    ap.add_argument('--normal', action='store_true', help='nomes de 17 letras (navegador de 32 colunas)')
    a = ap.parse_args()
    if not os.path.isdir(a.cartao): sys.exit('nao existe: %s' % a.cartao)
    le_config()
    if not a.normal and CFG.has_option('opcoes', 'normal'):
        a.normal = CFG.getboolean('opcoes', 'normal')
    if not a.pasta and CFG.has_section('pastas'):       # sem --pasta: o config.ini
        for k, v in CFG.items('pastas'):
            a.pasta.append('%s=%s' % (v, k) if v else k)   # ROTULO = CAMINHO, ou so' NOME
        print('pastas da barra (config.ini): %s' % ' '.join(a.pasta))
    extra = (['--pasta'] + a.pasta if a.pasta else []) + (['--largura', '17'] if a.normal else [])
    corre('gera_nav.py', a.cartao, '--todos', *(['--fazer'] if a.fazer else []), *extra)   # todos os ficheiros
    if a.fazer:
        print('\nFeito. Agora "Ejetar" antes de tirar o cartao.')
    else:
        print('\n(nada foi mudado: repete com --fazer)')

if __name__ == '__main__':
    main()
